// @generated by luaudocs. Do not edit; regenerated by every build.
//
// Markdown rewrites and navigation landmarks installed as `markdown-it` core
// rules by the generated `config.mts`. Two provide Docusaurus compatibility
// (`:::note` admonitions become VitePress containers, and `<Tabs>` / `<TabItem>`
// groups become the tab strip markup that `::: code-group` renders); `<Frame>`
// is LuauDocs's own callout frame. Before block parsing, `luaudocs` rewrites
// those constructs and prepends each page's `<nav>` breadcrumb trail; after
// inline parsing (and before `anchor`), `luaudocs_frame_headings` converts
// headings inside `<Frame>` into unanchored `<hN>` tags so embedded sections
// keep VitePress link rewriting and dead-link checks without polluting the host
// page's outline or heading slugs.
//
// Because `syncSite` copies this file into user sites, it cannot import from
// `src/`; shared helpers live here and `src/markdown.ts` re-exports them.
import type MarkdownIt from "markdown-it";
import type StateCore from "markdown-it/lib/rules_core/state_core.mjs";

// CommonMark allows 0-3 leading spaces on fence openers/closers (a 4-space or
// tab indent opens an indented code block instead). Backtick fence info strings
// may not contain backticks.
const FENCE_OPENER = /^ {0,3}(`{3,}(?=[^`\r\n]*(?:\r?\n|$))|~{3,})/;
const FENCE_CLOSER = /^ {0,3}(`{3,}|~{3,})[ \t]*(?:\r?\n|$)/;

/**
 * Splits markdown into segments alternating between prose (even indices) and
 * fenced code blocks (odd indices) so rewrites leave fenced code verbatim. A
 * fence closes only on a marker of the same character at least as long as the
 * opener with only optional spaces or tabs trailing on the line. An
 * unterminated fence runs to the end of the string.
 */
export function splitFences(text: string): string[] {
	if (!text.includes("```") && !text.includes("~~~")) {
		return [text];
	}
	const parts: string[] = [];
	let start = 0;
	let offset = 0;
	let fence: string | undefined;
	for (const line of text.split(/(?<=\n)/)) {
		if (!fence) {
			const marker = FENCE_OPENER.exec(line)?.[1];
			if (marker) {
				parts.push(text.slice(start, offset));
				start = offset;
				fence = marker;
			}
		} else {
			const close = FENCE_CLOSER.exec(line)?.[1];
			if (close?.startsWith(fence)) {
				parts.push(text.slice(start, offset + line.length));
				start = offset + line.length;
				fence = undefined;
			}
		}
		offset += line.length;
	}
	parts.push(text.slice(start));
	return parts;
}

/** Returns the length of the longest contiguous backtick run in `text`. */
export function longestBacktickRun(text: string): number {
	let max = 0;
	for (const match of text.matchAll(/`+/g)) {
		if (match[0].length > max) {
			max = match[0].length;
		}
	}
	return max;
}

/**
 * Wraps `text` in a CommonMark code span that survives embedded backticks
 * (fencing with one more backtick than the longest run inside `text`, and
 * padding with spaces when `text` starts or ends with a backtick or has
 * symmetric outer spaces around non-space text that CommonMark would strip).
 */
export function codeSpan(text: string): string {
	const fence = "`".repeat(longestBacktickRun(text) + 1);
	const pad = text.startsWith("`") || text.endsWith("`") || /^ .*[^ ].* $/.test(text) ? " " : "";
	return `${fence}${pad}${text}${pad}${fence}`;
}

/** Escapes HTML special characters for element text and double-quoted attributes. */
export function escapeHtml(text: string): string {
	return text
		.replace(/&/g, "&amp;")
		.replace(/</g, "&lt;")
		.replace(/>/g, "&gt;")
		.replace(/"/g, "&quot;");
}

/**
 * Backslash-escapes inline markdown punctuation so identifiers like `_x_` or
 * `<T>` render literally rather than as emphasis or HTML tags. `markdown-it`
 * strips backslash escapes before computing heading slugs, so escaping a heading
 * title does not change its anchor.
 */
export function escapeMarkdown(text: string): string {
	return text.replace(/[\\`*_[\]<>{}!#~&:|]/g, "\\$&");
}

/**
 * Rejects executable or inline-document URL schemes (`javascript:`, `vbscript:`,
 * `data:`) after stripping ASCII control and whitespace characters the way
 * browsers normalize `href` attributes.
 */
export function isSafeHref(url: string): boolean {
	const normalized = url.replace(/[\u0000-\u0020\u007f]+/g, "");
	return !/^(?:javascript|vbscript|data):/i.test(normalized);
}

/**
 * Percent-encodes whitespace, quotes, angle brackets, backslashes, and backticks
 * so a URL is safe inside markdown link destinations and fence link tables.
 */
export function encodeHref(url: string): string {
	return url.replace(/[\s<>"\\`]/g, (char) => encodeURIComponent(char));
}

/**
 * Formats a URL as a safe markdown link destination, wrapping it in `<...>`
 * when it contains parentheses.
 */
export function linkDestination(url: string): string {
	const safe = encodeHref(url);
	return /[()]/.test(safe) ? `<${safe}>` : safe;
}

/** Docusaurus admonition kinds -> VitePress container kinds. */
const ADMONITION_MAP: Record<string, string> = {
	note: "info",
	tip: "tip",
	info: "info",
	caution: "warning",
	warning: "warning",
	danger: "danger",
};

/**
 * Rewrites Docusaurus admonition openers (`:::note`, `:::caution`, and
 * Docusaurus 3's bracketed `:::tip[Title]`) into VitePress container openers
 * (`::: info`, `::: warning`, `::: tip Title`). Unknown container kinds and
 * closing `:::` lines pass through unchanged.
 */
function rewriteAdmonitions(text: string): string {
	return text.replace(
		/^( {0,3}):::(\w+)(.*)$/gm,
		(match, indent: string, kind: string, rest: string) => {
			const mapped = ADMONITION_MAP[kind.toLowerCase()];
			if (!mapped) {
				return match;
			}
			const title = rest.match(/^\[([^\]]*)\][ \t\r]*$/);
			return `${indent}::: ${mapped}${title ? ` ${title[1]}` : rest}`;
		},
	);
}

/** Component tags handled by `rewriteMarkup`, exported for the Moonwave converter's report. */
export const REWRITTEN_COMPONENTS = ["Tabs", "TabItem", "Frame"] as const;

/**
 * Matches a block-level JSX element whose opening and closing tags sit on their
 * own lines with up to 3 leading spaces (group 1: attributes, group 2: inner body).
 */
function blockElement(tag: string): RegExp {
	return new RegExp(
		`^ {0,3}<${tag}\\b([^>]*)>[ \\t]*\\r?\\n([\\s\\S]*?)^ {0,3}<\\/${tag}>[ \\t]*\\r?$`,
		"gm",
	);
}

const TAB_GROUP = blockElement("Tabs");
const TAB_ITEM = /<TabItem\b([^>]*)>([\s\S]*?)<\/TabItem>/g;
const FRAME = blockElement("Frame");
// Null-byte sentinel used to mask fenced code blocks during component matching.
const MARK = "\u0000";
const MASKED_FENCE = new RegExp(`^${MARK}(\\d+)${MARK}$`);
const MASKED_FENCES = new RegExp(`${MARK}(\\d+)${MARK}`, "g");
// The opening line of a fenced code block (where VitePress reads `active`).
const FENCE_INFO = /^ {0,3}(?:`{3,}|~{3,})[^\r\n]*/;
// A VitePress fence title (` [init.luau]`) on the fence opener line. Requires
// leading whitespace so `luaudocs-links=[[...]]` is never stripped as a title.
const FENCE_TITLE = /[ \t]+\[(?:[^[\]]|\[[^[\]]*\])*\]/;

/** Returns the trailing newline separator before a closing HTML tag (a masked fence already carries its own trailing newline). */
function closeGap(body: string): string {
	return body.endsWith(MARK) ? "\n" : "\n\n";
}

const ATTR_PATTERNS = {
	label: /\blabel\s*=\s*(["'])(.*?)\1/,
	value: /\bvalue\s*=\s*(["'])(.*?)\1/,
	link: /\blink\s*=\s*(["'])(.*?)\1/,
} as const;

/** Reads a double- or single-quoted attribute from an opening tag's attribute string. */
function attr(attrs: string, name: keyof typeof ATTR_PATTERNS): string | undefined {
	return ATTR_PATTERNS[name].exec(attrs)?.[2];
}

/** Tests for Docusaurus's boolean `default` attribute on `<TabItem>` after stripping quoted attribute values. */
function isDefault(attrs: string): boolean {
	return /\bdefault\b/.test(attrs.replace(/(["']).*?\1/g, ""));
}

/**
 * Rewrites Docusaurus/Moonwave `<Tabs>` and `<TabItem>` blocks into the HTML
 * structure that VitePress's `::: code-group` container produces. Emitting the
 * container's HTML structure directly allows tabs to hold arbitrary prose and
 * multiple blocks while reusing VitePress's built-in tab styling and switching.
 */
function rewriteTabs(masked: string, fences: string[]): string {
	// Radio input `name` attributes must be unique per group on a page.
	let groups = 0;
	return masked.replace(TAB_GROUP, (group, _attrs: string, body: string) => {
		const items = [...body.matchAll(TAB_ITEM)].map(([, attrs = "", content = ""]) => {
			const text = content.trim();
			const marker = text.match(MASKED_FENCE);
			return {
				// Fall back to `value` when `label` is omitted, matching Docusaurus.
				label: attr(attrs, "label") ?? attr(attrs, "value") ?? "",
				default: isDefault(attrs),
				body: text,
				fenceIndex: marker ? Number(marker[1]) : undefined,
			};
		});
		if (items.length === 0) {
			return group;
		}
		const top = Math.max(
			items.findIndex((item) => item.default),
			0,
		);
		const id = `tabs-${groups++}`;
		const strip = items
			.map((item, index) => {
				// Set `data-title` on the `<label>` so `vitepress-plugin-group-icons`
				// attaches the matching file-type or tool icon.
				const label = escapeHtml(item.label);
				return (
					`<input type="radio" name="${id}" id="${id}-${index}"${index === top ? " checked" : ""}>` +
					`<label data-title="${label}" for="${id}-${index}">${label}</label>`
				);
			})
			.join("");
		const panels = items.map((item, index) => {
			if (item.fenceIndex !== undefined) {
				// When a tab contains a single code fence, the fence itself is the
				// panel; strip any `[title]` from the fence opener since the tab
				// label already names it. Mutate the masked entry in place and keep
				// the sentinel in the document so `rewriteFrames` and
				// `rewriteAdmonitions` cannot rewrite inside the code fence.
				const fence = fences[item.fenceIndex]!.replace(FENCE_INFO, (line) => {
					const bare = line.replace(FENCE_TITLE, "");
					return index === top ? `${bare} active` : bare;
				});
				fences[item.fenceIndex] = fence.trimEnd();
				return item.body;
			}
			return (
				`<div class="vp-block${index === top ? " active" : ""}">\n\n` +
				`${item.body}${closeGap(item.body)}</div>`
			);
		});
		// Keep blank lines around panels and closing `</div>` tags so `markdown-it`
		// parses the inner markdown rather than treating it as part of a raw HTML block.
		return (
			`<div class="vp-code-group"><div class="tabs">${strip}</div><div class="blocks">\n\n` +
			`${panels.join("\n\n")}\n\n</div></div>`
		);
	});
}

/**
 * Rewrites `<Frame>` into a bordered callout block with an optional top-border
 * caption (`label`, optionally linked via `link`).
 *
 * Emits linked captions and the frame body as markdown separated by blank lines
 * so VitePress prefixes the site `base`, runs its dead-link check, and parses
 * headings and inline constructs through `markdown-it`.
 */
function rewriteFrames(masked: string): string {
	return masked.replace(FRAME, (_frame, attrs: string, body: string) => {
		const label = attr(attrs, "label");
		const link = attr(attrs, "link");
		let caption = "";
		if (label !== undefined) {
			caption =
				link === undefined || !isSafeHref(link)
					? `<div class="luaudocs-frame-label">${escapeHtml(label)}</div>\n`
					: `<div class="luaudocs-frame-label">\n\n[${escapeMarkdown(label)}` +
						`<span class="luaudocs-frame-arrow">&#8594;</span>](${linkDestination(link)})` +
						`\n\n</div>\n`;
		}
		const content = body.trim();
		return `<div class="luaudocs-frame">\n${caption}\n${content}${closeGap(content)}</div>`;
	});
}

function withMaskedFences(
	text: string,
	transform: (masked: string, fences: string[]) => string,
): string {
	const fences: string[] = [];
	const masked = splitFences(text)
		.map((part, index) => {
			if (index % 2 === 0) {
				return part;
			}
			// Keep the fence's trailing newline outside the marker so line-anchored
			// regexes still match on the line immediately following a code block.
			const newline = part.endsWith("\n") ? "\n" : "";
			const body = newline === "" ? part : part.slice(0, -1);
			return MARK + (fences.push(body) - 1) + MARK + newline;
		})
		.join("");
	return transform(masked, fences).replace(
		MASKED_FENCES,
		(_marker, index: string) => fences[Number(index)]!,
	);
}

/**
 * Removes `<Frame>...</Frame>` blocks outside fenced code blocks so anchor
 * prediction in `src/markdown.ts` skips framed headings just as
 * `installFrameHeadingRule` does at render time.
 */
export function stripFrames(text: string): string {
	if (!text.includes("<Frame")) {
		return text;
	}
	return withMaskedFences(text, (masked) => masked.replace(FRAME, ""));
}

/**
 * Runs `<Tabs>`, `<Frame>`, and admonition rewrites over a markdown document
 * while masking fenced code blocks with null-byte markers so code examples stay
 * untouched.
 */
export function rewriteMarkup(text: string): string {
	const tabs = text.includes("<Tabs");
	const frames = text.includes("<Frame");
	const admonitions = /^ {0,3}:::\w/m.test(text);
	if (!tabs && !frames && !admonitions) {
		return text;
	}
	return withMaskedFences(text, (masked, fences) => {
		let rewritten = masked;
		if (tabs) {
			rewritten = rewriteTabs(rewritten, fences);
		}
		if (frames) {
			rewritten = rewriteFrames(rewritten);
		}
		if (admonitions) {
			rewritten = rewriteAdmonitions(rewritten);
		}
		return rewritten;
	});
}

const DIV_TAG = /<\/?div(?=[\s>/])(?:"[^"]*"|'[^']*'|[^>"'])*>/gi;
const CLASS_ATTR = /\bclass\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>"']+))/i;

function hasFrameClass(tag: string): boolean {
	const match = CLASS_ATTR.exec(tag);
	const classes = match?.[1] ?? match?.[2] ?? match?.[3] ?? "";
	return classes.split(/\s+/).includes("luaudocs-frame");
}

/**
 * Installs a `markdown-it` core token pass before `anchor` that converts
 * `heading_open` and `heading_close` tokens inside `<div class="luaudocs-frame">`
 * into `html_block` `<hN>` tags without `id` attributes. Keeping the middle
 * `inline` token intact preserves `<code v-pre>`, `{.attrs}`, link `base`
 * prefixing, `validateLink` scheme checks, and VitePress dead-link recording,
 * while preventing `anchor` and VitePress's outline extractor from indexing
 * quoted headings.
 */
export function installFrameHeadingRule(md: MarkdownIt): void {
	const rule = (state: StateCore): boolean => {
		let divDepth = 0;
		const frameBaseDepths: number[] = [];
		const scanHtml = (html: string) => {
			for (const [tag] of html.replace(/<!--[\s\S]*?-->/g, "").matchAll(DIV_TAG)) {
				if (tag.startsWith("</")) {
					if (divDepth > 0) {
						divDepth -= 1;
					}
					while (
						frameBaseDepths.length > 0 &&
						divDepth <= frameBaseDepths[frameBaseDepths.length - 1]!
					) {
						frameBaseDepths.pop();
					}
				} else if (!/\/\s*>$/.test(tag)) {
					if (hasFrameClass(tag)) {
						frameBaseDepths.push(divDepth);
					}
					divDepth += 1;
				}
			}
		};

		for (const tok of state.tokens) {
			if (tok.type === "html_block") {
				scanHtml(tok.content);
			} else if (tok.type === "inline" && tok.children) {
				for (const child of tok.children) {
					if (child.type === "html_inline") {
						scanHtml(child.content);
					}
				}
			} else if (frameBaseDepths.length > 0 && tok.type === "heading_open") {
				const tag = tok.tag;
				const attrs = md.renderer.renderAttrs(tok);
				tok.type = "html_block";
				tok.tag = "";
				tok.content = `<${tag}${attrs}>`;
			} else if (frameBaseDepths.length > 0 && tok.type === "heading_close") {
				const tag = tok.tag;
				tok.type = "html_block";
				tok.tag = "";
				tok.content = `</${tag}>\n`;
			}
		}
		return true;
	};

	try {
		md.core.ruler.before("anchor", "luaudocs_frame_headings", rule);
	} catch {
		md.core.ruler.push("luaudocs_frame_headings", rule);
	}
}

/*
 * ------------------------------------------------------------------ page trail
 */

/** One breadcrumb step in a page's navigation trail (`link` is omitted for unindexed folders). */
export interface TrailSegment {
	text: string;
	link?: string;
}

/** Baked map of docs-relative markdown paths to breadcrumb trails. */
export type PageTrails = Record<string, TrailSegment[] | undefined>;

/**
 * Prepends a page's breadcrumb trail above its title. Emits markdown links
 * inside `<nav class="luaudocs-trail" aria-label="Breadcrumb">` (surrounded by
 * blank lines) so VitePress applies the site `base` and dead-link check, and
 * places the trail before the H1 heading so VitePress's local search indexer
 * ignores it.
 */
export function prependTrail(source: string, trail: TrailSegment[] | undefined): string {
	if (trail === undefined || trail.length === 0) {
		return source;
	}
	const steps = trail
		.map((step) => {
			const label = escapeMarkdown(step.text);
			return step.link === undefined || !isSafeHref(step.link)
				? label
				: `[${label}](${linkDestination(step.link)})`;
		})
		.join(" › ");
	return `<nav class="luaudocs-trail" aria-label="Breadcrumb">\n\n${steps}\n\n</nav>\n\n${source}`;
}

/**
 * Installs the `markdown-it` core rules that run `rewriteMarkup` and
 * `prependTrail` before block parsing and unlist `<Frame>` headings before
 * anchor generation.
 */
export function installMarkupRule(md: MarkdownIt, trails: PageTrails): void {
	md.core.ruler.before("block", "luaudocs", (state) => {
		const page = (state.env as { relativePath?: string } | null)?.relativePath ?? "";
		state.src = prependTrail(rewriteMarkup(state.src), trails[page]);
		return true;
	});
	installFrameHeadingRule(md);
}
